import{_ as a,o as r,c as s,a4 as e}from"./chunks/framework.vNSRaLQv.js";const p=JSON.parse('{"title":"Java GraalVM Native Image vs JRE 对比","description":"","frontmatter":{"title":"Java GraalVM Native Image vs JRE 对比","date":"2026-08-04T00:00:00.000Z"},"headers":[],"relativePath":"posts/10-java-native-vs-jre-comparison.md","filePath":"posts/10-java-native-vs-jre-comparison.md"}'),d={name:"posts/10-java-native-vs-jre-comparison.md"};function o(n,t,i,g,l,h){return r(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="java-graalvm-native-image-vs-jre-对比" tabindex="-1">Java GraalVM Native Image vs JRE 对比 <a class="header-anchor" href="#java-graalvm-native-image-vs-jre-对比" aria-label="Permalink to &quot;Java GraalVM Native Image vs JRE 对比&quot;">​</a></h1><h2 id="_1-单服务对比" tabindex="-1">1. 单服务对比 <a class="header-anchor" href="#_1-单服务对比" aria-label="Permalink to &quot;1. 单服务对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>传统 JRE（Spring Boot + JVM）</th><th>GraalVM Native Image</th></tr></thead><tbody><tr><td><strong>启动速度</strong></td><td>3~10 秒（Spring 加载 Bean、IoC 扫描）</td><td>30~100ms（无反射/类加载开销）</td></tr><tr><td><strong>运行时内存</strong></td><td>基础 200~400MB，峰值 500MB+</td><td>基础 15~40MB，峰值 80~120MB，约 <strong>1/10</strong></td></tr><tr><td><strong>运行性能</strong></td><td>JIT 预热后峰值性能高</td><td>起步即峰值，但峰值略慢 10~20%（无 JIT）</td></tr><tr><td><strong>硬盘体积</strong></td><td>JAR 20~50MB + JRE 200~300MB = <strong>250~350MB</strong></td><td>单一静态链接二进制，<strong>40~80MB</strong></td></tr></tbody></table><h2 id="_2-多微服务场景-8-服务-单机" tabindex="-1">2. 多微服务场景（8 服务，单机） <a class="header-anchor" href="#_2-多微服务场景-8-服务-单机" aria-label="Permalink to &quot;2. 多微服务场景（8 服务，单机）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>8 服务共享 1 个 JRE</th><th>8 服务各自 GraalVM Native</th></tr></thead><tbody><tr><td><strong>JDK/JRE</strong></td><td>1 份 JRE = ~250MB</td><td>0（已静态链接进二进制）</td></tr><tr><td><strong>应用本身</strong></td><td>8 × JAR（~35MB）= 280MB</td><td>8 × 二进制（~55MB）= 440MB</td></tr><tr><td><strong>硬盘总计</strong></td><td>~530MB</td><td>~440MB（略小）</td></tr><tr><td><strong>运行时内存</strong></td><td>8 × 300MB = <strong>~2.4GB</strong></td><td>8 × 30MB = <strong>~240MB（1/10）</strong></td></tr><tr><td><strong>启动总时间</strong></td><td>8 × 3~10 秒 = 24~80 秒</td><td>8 × 50ms = <strong>~400ms（100 倍快）</strong></td></tr></tbody></table><p><strong>结论：</strong> 硬盘体积相当（Native 反而小 ~90MB）。真正差距在 <strong>运行时内存</strong>（2.4GB → 240MB）和 <strong>启动速度</strong>（半分钟 → 瞬间）。</p><h2 id="_3-对-mybilibili-架构的选型" tabindex="-1">3. 对 mybilibili 架构的选型 <a class="header-anchor" href="#_3-对-mybilibili-架构的选型" aria-label="Permalink to &quot;3. 对 mybilibili 架构的选型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>服务</th><th>语言</th><th>选型理由</th></tr></thead><tbody><tr><td><strong>media</strong></td><td>Java GraalVM</td><td>需要 FFmpeg/Whisper AI 子进程 + Java 生态成熟库</td></tr><tr><td><strong>store</strong></td><td>Java GraalVM</td><td>支付事务、Spring 生态成熟，订单/支付库丰富</td></tr><tr><td><strong>gateway</strong></td><td><strong>Go</strong></td><td>单二进制 10~15MB，内存 10~20MB，比 Native Image 更小更快</td></tr><tr><td><strong>core</strong></td><td><strong>Go</strong></td><td>同上，纯业务逻辑，无 Java 生态依赖</td></tr><tr><td><strong>realtime</strong></td><td><strong>Go</strong></td><td>WebSocket + 高并发，Go 天生优势</td></tr><tr><td><strong>search</strong></td><td><strong>Go</strong></td><td>Bleve 本身就是 Go 嵌入式库</td></tr><tr><td><strong>ads</strong></td><td><strong>Go</strong></td><td>轻量计费/规则引擎</td></tr></tbody></table><p><strong>二进制体积对比：</strong> 5 个 Go 服务（~15MB/个）+ 2 个 Java Native（~55MB/个）≈ <strong>185MB 硬盘</strong><strong>运行时内存：</strong> 5 个 Go（~15MB/个）+ 2 个 Java Native（~30MB/个）≈ <strong>135MB 运行时</strong></p><p>盒子（1GB RAM）上完全无压力，还能从容跑 Redis/etcd 等基础设施。</p><h2 id="_4-native-image-的代价" tabindex="-1">4. Native Image 的代价 <a class="header-anchor" href="#_4-native-image-的代价" aria-label="Permalink to &quot;4. Native Image 的代价&quot;">​</a></h2><ul><li>构建慢：每次 3~5 分钟（AOT 编译 + 静态链接）</li><li>反射/动态代理需提前配置 <code>reflect-config.json</code></li><li>某些 Java 库不兼容（如动态类加载、Serialization）</li><li>调试不方便（无 JVM 工具链）</li></ul><h2 id="_5-总结" tabindex="-1">5. 总结 <a class="header-anchor" href="#_5-总结" aria-label="Permalink to &quot;5. 总结&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>单服务：   JRE 300MB 内存 vs Native 30MB 内存 → 10 倍差距</span></span>
<span class="line"><span>8 服务：   JRE 2.4GB 内存 vs Native 240MB 内存 → 10 倍差距</span></span>
<span class="line"><span>硬盘：     JRE 530MB   vs Native 440MB         → 基本持平</span></span>
<span class="line"><span>启动：     JRE 半分钟  vs Native 瞬间          → 100 倍差距</span></span></code></pre></div><p><strong>结论：</strong> 对盒子/手机场景，Native Image 是必选项。media + store 用 Java GraalVM，其余 5 个服务用 Go，磁盘和内存都最优。</p>`,15)])])}const c=a(d,[["render",o]]);export{p as __pageData,c as default};
